}

.example:hover {
    border-color: var(--accent);
    box-shadow: 0 2px 12px rgba(138, 180, 248, 0.1);
}

.faq-button {
    width: 100%;
    padding: 1.25rem;
    background: none;
    border: none;
    color: var(--text-primary);
    font-size: 1.1rem;
    font-weight: 500;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    transition: all 0.2s ease;
    text-align: left;
}

.faq-button:hover {
    background-color: var(--bg-tertiary);
    color: var(--accent-hover);
}

.faq-button:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: -2px;
    background-color: var(--bg-tertiary);
}

.question-text {
    flex: 1;
}

.toggle-icon {
    display: inline-block;
    width: 24px;
    height: 24px;
    background: linear-gradient(135deg, var(--accent) 0%, var(--accent) 49%, transparent 49%, transparent 51%, var(--accent) 51%, var(--accent) 100%),
